import logging
import os.path
from functools import wraps
from mock import Mock
from taf.ul.ettf.utils.paths import test_name, is_robot_context_available, base_logs_directory
import robot.api.logger


DEFAULT_LOG_FILENAME = 'test_execution.log'


def create_logger(name):
    logger = logging.getLogger('[{}]'.format(name))
    logger.setLevel(logging.DEBUG)
    return logger


def create_console_handler():
    console_handler = logging.StreamHandler()
    console_handler.setLevel(logging.INFO)
    return console_handler


def append_testname(msg):
    testname = '[{}] '.format(test_name()) if test_name() else ''
    msg = str(msg)
    if not msg.startswith(testname):
        msg = '{}{}'.format(testname, msg)
    return msg


def append_logger_name(msg, logger_name):
    return '[ettf]{}: {}'.format(logger_name, msg)


def testname_info():
    class TestnameInfo(logging.Filter):
        def filter(self, record):
            record.msg = append_testname(record.msg)
            return True

    return TestnameInfo()


def create_file_handler(filename):
    file_handler = logging.FileHandler(filename)
    file_handler.setLevel(logging.DEBUG)
    formatter = logging.Formatter('[%(asctime)s] %(name)-20s %(threadName)-40s %(levelname)-8s %(message)-120s [%(pathname)s:%(lineno)d]')
    file_handler.setFormatter(formatter)
    return file_handler


ROBOT_LOG_LEVEL_HANDLERS = {
    50: lambda logger, msg: logger.error(msg),                                   # CRITICAL
    40: lambda logger, msg: logger.error(msg),                                   # ERROR
    30: lambda logger, msg: logger.warn(msg),                                    # WARNING
    20: lambda logger, msg: logger.info('\n{}'.format(msg), also_console=True),  # INFO
    10: lambda logger, msg: logger.debug(msg),                                   # DEBUG
    0: lambda logger, msg: logger.debug(msg)                                     # NOTSET
}


class LazyLogger(logging.getLoggerClass()):
    def __init__(self, name, filename, disable_html_logging):
        self.robot_logger = Mock()
        self.filename = filename
        self.disable_html_logging = disable_html_logging
        super(LazyLogger, self).__init__('[{}]'.format(name))

    def _log(self, level, msg, args, exc_info=None, extra=None):
        self._init()
        ROBOT_LOG_LEVEL_HANDLERS[level](self.robot_logger, append_testname(append_logger_name(msg, self.name)))
        super(LazyLogger, self)._log(level, msg, args, exc_info, extra)

    def _init(self):
        self.setLevel(logging.DEBUG)
        self.addFilter(testname_info())
        self.addHandler(create_file_handler(self._filepath()))

        if not is_robot_context_available():
            self.addHandler(create_console_handler())
        elif not self.disable_html_logging:
            self.robot_logger = robot.api.logger

        self._disable_initialization()

    def _disable_initialization(self):
        self._init = self._empty

    def _empty(self):
        pass

    def _filepath(self):
        return os.path.join(base_logs_directory(), self.filename)


def custom_logger(name, filename=DEFAULT_LOG_FILENAME, disable_html_logging=False):
    return LazyLogger(name, filename, disable_html_logging)


def log(start_log, end_log, logger=custom_logger('DefaultLogger')):
    def _log(f):
        @wraps(f)
        def wrapper(*args, **kwargs):
            logger.info(start_log)
            result = f(*args, **kwargs)
            logger.info(end_log)
            return result
        return wrapper
    return _log
